import re
from datetime import datetime


def _require_match(pattern, text, flags=0):
    m = re.search(pattern, text, flags)
    if not m:
        raise ValueError("Required label missing")
    return m


def _parse_date(date_str):
    s = re.sub(r"^\s*[A-Za-z]+,\s*", "", date_str.strip())
    for fmt in ("%d %B %Y", "%d %b %Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    raise ValueError("Invalid date format")


def _parse_time(time_str):
    s = re.sub(r"\s+", " ", time_str.strip().upper())
    try:
        return datetime.strptime(s, "%I:%M %p").strftime("%H:%M")
    except ValueError:
        raise ValueError("Invalid time format")


def extract(text: str) -> dict:
    person_m = _require_match(r"Appointment\s+confirmed\s+for\s+(.+?)\s+with\s+Dr\.", text, re.IGNORECASE)
    date_m = _require_match(r"^\s*Date:\s*([^\n]+)", text, re.IGNORECASE | re.MULTILINE)
    time_m = _require_match(r"^\s*Time:\s*([^\n]+)", text, re.IGNORECASE | re.MULTILINE)

    person = person_m.group(1).strip()
    due_date = _parse_date(date_m.group(1))
    event_time = _parse_time(time_m.group(1))

    return {
        "type": "meeting",
        "provider": "Apollo Clinic",
        "currency": "INR",
        "due_date": due_date,
        "event_time": event_time,
        "person": person,
    }
